-- Official consumer UI: server-owned preferences and financial workspaces.
CREATE TABLE core.consumer_commands(id uuid PRIMARY KEY,issuer text NOT NULL,subject text NOT NULL,client_id text NOT NULL,request_key uuid NOT NULL,person_id uuid NOT NULL,action text NOT NULL,input jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(issuer,subject,client_id,request_key));
CREATE TRIGGER immutable_consumer_commands BEFORE UPDATE OR DELETE OR TRUNCATE ON core.consumer_commands FOR EACH STATEMENT EXECUTE FUNCTION core.immutable_journal();
CREATE TABLE core.consumer_preferences(person_id uuid PRIMARY KEY,document jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_vaults(id uuid PRIMARY KEY,person_id uuid NOT NULL,name text NOT NULL,target_minor bigint NOT NULL CHECK(target_minor>0),target_date date,icon text NOT NULL DEFAULT '✦',locked boolean NOT NULL DEFAULT false,mutual boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_members(vault_id uuid NOT NULL REFERENCES core.consumer_vaults(id),person_id uuid NOT NULL,state text NOT NULL CHECK(state IN('INVITED','ACTIVE')),PRIMARY KEY(vault_id,person_id));
CREATE TABLE core.consumer_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),person_id uuid NOT NULL,category text NOT NULL,title text NOT NULL,body text NOT NULL,route text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_budgets(person_id uuid NOT NULL,category text NOT NULL,limit_minor bigint NOT NULL CHECK(limit_minor>0),rollover boolean NOT NULL DEFAULT false,threshold integer NOT NULL DEFAULT 80 CHECK(threshold BETWEEN 1 AND 100),PRIMARY KEY(person_id,category));
CREATE TABLE core.consumer_cards(id uuid PRIMARY KEY,person_id uuid NOT NULL,account_id uuid NOT NULL REFERENCES core.account_registry(id),label text NOT NULL,last_four text NOT NULL,frozen boolean NOT NULL DEFAULT false,online_enabled boolean NOT NULL DEFAULT true,atm_enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_links(id uuid PRIMARY KEY,person_id uuid NOT NULL,institution text NOT NULL,label text NOT NULL,last_four text NOT NULL,state text NOT NULL DEFAULT 'VERIFIED_SYNTHETIC',created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_bills(id uuid PRIMARY KEY,person_id uuid NOT NULL,merchant text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),next_date date NOT NULL,state text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_metadata(account_id uuid NOT NULL REFERENCES core.account_registry(id),batch_id uuid NOT NULL REFERENCES core.journal_batches(id),person_id uuid NOT NULL,category text NOT NULL DEFAULT 'Other',note text NOT NULL DEFAULT '',receipt jsonb,PRIMARY KEY(account_id,batch_id));
CREATE TABLE core.consumer_requests(id uuid PRIMARY KEY,person_id uuid NOT NULL,recipient_person uuid NOT NULL,account_id uuid NOT NULL REFERENCES core.account_registry(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),memo text NOT NULL,state text NOT NULL DEFAULT 'REQUESTED',payment_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE core.consumer_authorizations(id uuid PRIMARY KEY,person_id uuid NOT NULL,actor_context jsonb NOT NULL,action text NOT NULL,details jsonb NOT NULL,digest text NOT NULL,challenge_id uuid NOT NULL UNIQUE,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '3 minutes');
CREATE TRIGGER immutable_consumer_authorizations BEFORE UPDATE OR DELETE OR TRUNCATE ON core.consumer_authorizations FOR EACH STATEMENT EXECUTE FUNCTION core.immutable_journal();
CREATE TABLE core.consumer_tokens(id uuid PRIMARY KEY,person_id uuid NOT NULL,actor_context jsonb NOT NULL,label text NOT NULL,scope text NOT NULL CHECK(scope IN('accounts:read','transactions:read','portfolio:read')),secret_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '30 days',revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
INSERT INTO core.ledger_accounts(id,kind,state,debit_blocked) VALUES('4f1a780b-3e31-48ef-a294-000000000020','CONTROL','ACTIVE',false),('4f1a780b-3e31-48ef-a294-000000000021','CONTROL','ACTIVE',false) ON CONFLICT(id) DO NOTHING;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['consumer_commands','consumer_preferences','consumer_vaults','consumer_members','consumer_notifications','consumer_budgets','consumer_cards','consumer_links','consumer_bills','consumer_metadata','consumer_requests','consumer_authorizations','consumer_tokens'] LOOP EXECUTE format('REVOKE ALL ON core.%I FROM bank_core',t);EXECUTE format('GRANT SELECT ON core.%I TO bank_core',t);END LOOP;END $$;
CREATE FUNCTION core.consumer_actor(p_actor jsonb,p_person uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$ BEGIN
 PERFORM documents.require_periodic_actor(p_actor,p_person,false);
 IF p_actor->>'clientId' NOT IN('customer-web','bank-mobile') THEN RAISE EXCEPTION 'Customer channel required';END IF;
END $$;
CREATE FUNCTION core.consumer_account(p_account uuid,p_person uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$ BEGIN
 PERFORM 1 FROM core.ledger_accounts WHERE id=p_account AND kind='CUSTOMER' AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active account unavailable';END IF;
 PERFORM 1 FROM core.account_relationships WHERE account_id=p_account AND person_id=p_person AND kind='OWNER' AND revoked_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Current account ownership required';END IF;
END $$;
CREATE FUNCTION core.consumer_minor(p_value text) RETURNS bigint LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ BEGIN
 IF p_value IS NULL OR p_value!~'^[1-9][0-9]{0,18}$' OR p_value::numeric>9223372036854775807 THEN RAISE EXCEPTION 'Positive exact minor units required';END IF;RETURN p_value::bigint;END $$;
CREATE FUNCTION core.consumer_post(p_operation uuid,p_kind text,p_from uuid,p_to uuid,p_minor bigint,p_hold uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$
DECLARE b uuid;made boolean;e jsonb;BEGIN
 SELECT r.batch_id,r.created INTO b,made FROM core.post(p_operation,p_kind,jsonb_build_array(jsonb_build_object('accountId',p_from,'delta',-p_minor),jsonb_build_object('accountId',p_to,'delta',p_minor)),p_hold) r;
 IF made THEN e:=jsonb_build_object('eventId',b,'eventType','journal.batch-posted','schemaVersion',1,'producer','core','aggregateId',b,'aggregateVersion',1,'occurredAt',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'correlationId',p_operation,'causationId',p_operation::text,'data',jsonb_build_object('batchId',b,'operationId',p_operation));INSERT INTO core.outbox(event_id,aggregate_id,aggregate_version,document,fingerprint) VALUES(b,b,1,e,encode(sha256(convert_to(core.periodic_policy_canonical(e),'UTF8')),'hex'));END IF;RETURN b;END $$;
CREATE FUNCTION core.consumer_authorize(p_actor jsonb,p_person uuid,p_action text,p_details jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$
DECLARE target uuid:=gen_random_uuid();challenge uuid:=gen_random_uuid();digest text;nonce text;BEGIN
 PERFORM core.consumer_actor(p_actor,p_person);digest:=encode(sha256(convert_to(core.periodic_policy_canonical(jsonb_build_object('action',p_action,'details',p_details)),'UTF8')),'hex');nonce:=encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex');
 INSERT INTO controls.approval_challenges(id,operation_id,issuer,subject,person_id,intent_digest,nonce,state,expires_at) VALUES(challenge,target,p_actor->>'issuer',p_actor->>'subject',p_person,digest,nonce,'PENDING',clock_timestamp()+interval '3 minutes');
 INSERT INTO core.consumer_authorizations(id,person_id,actor_context,action,details,digest,challenge_id) VALUES(target,p_person,p_actor,p_action,p_details,digest,challenge);
 RETURN jsonb_build_object('id',target,'action',p_action,'details',p_details,'digest',digest,'approvalUrl','/auth/customer/step-up/'||challenge,'expiresAt',clock_timestamp()+interval '3 minutes','approvalReady',false);
END $$;
CREATE FUNCTION core.consumer_approval(p_actor jsonb,p_person uuid,p_id uuid,p_action text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$
DECLARE a core.consumer_authorizations;BEGIN
 PERFORM core.consumer_actor(p_actor,p_person);SELECT * INTO STRICT a FROM core.consumer_authorizations WHERE id=p_id AND person_id=p_person FOR SHARE;
 IF a.action IS DISTINCT FROM p_action OR a.actor_context->>'issuer' IS DISTINCT FROM p_actor->>'issuer' OR a.actor_context->>'subject' IS DISTINCT FROM p_actor->>'subject' OR a.actor_context->>'clientId' IS DISTINCT FROM p_actor->>'clientId' OR a.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Current exact action authorization required';END IF;
 IF a.digest IS DISTINCT FROM encode(sha256(convert_to(core.periodic_policy_canonical(jsonb_build_object('action',a.action,'details',a.details)),'UTF8')),'hex') THEN RAISE EXCEPTION 'Authorization integrity conflict';END IF;
 IF EXISTS(SELECT 1 FROM core.consumer_commands WHERE person_id=p_person AND input->>'authorizationId'=a.id::text) THEN RAISE EXCEPTION 'Authorization already executed; replay the original request key';END IF;
 UPDATE identity.step_up_proofs SET use_operation_id=a.id WHERE challenge_id=a.challenge_id AND issuer=p_actor->>'issuer' AND subject=p_actor->>'subject' AND intent_digest=a.digest AND expires_at>clock_timestamp() AND (use_operation_id IS NULL OR use_operation_id=a.id);
 IF NOT FOUND THEN RAISE EXCEPTION 'Fresh action-bound issuer reauthentication required';END IF;RETURN a.details;
END $$;
CREATE FUNCTION core.consumer_authorization(p_actor jsonb,p_person uuid,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$
DECLARE a core.consumer_authorizations;BEGIN PERFORM core.consumer_actor(p_actor,p_person);SELECT * INTO STRICT a FROM core.consumer_authorizations WHERE id=p_id AND person_id=p_person AND actor_context->>'issuer'=p_actor->>'issuer' AND actor_context->>'subject'=p_actor->>'subject' AND actor_context->>'clientId'=p_actor->>'clientId';RETURN jsonb_build_object('id',a.id,'action',a.action,'details',a.details,'digest',a.digest,'approvalUrl','/auth/customer/step-up/'||a.challenge_id,'expiresAt',a.expires_at,'receipt',(SELECT result FROM core.consumer_commands WHERE person_id=p_person AND input->>'authorizationId'=a.id::text LIMIT 1),'approvalReady',a.expires_at>clock_timestamp() AND EXISTS(SELECT 1 FROM identity.step_up_proofs WHERE challenge_id=a.challenge_id AND intent_digest=a.digest AND issuer=p_actor->>'issuer' AND subject=p_actor->>'subject' AND expires_at>clock_timestamp() AND (use_operation_id IS NULL OR use_operation_id=a.id)));END $$;
CREATE FUNCTION core.consumer_notify(p_person uuid,p_category text,p_title text,p_body text,p_route text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$ BEGIN
 IF coalesce((SELECT (document->>'notifications')::boolean FROM core.consumer_preferences WHERE person_id=p_person),true) THEN INSERT INTO core.consumer_notifications(person_id,category,title,body,route) VALUES(p_person,p_category,p_title,p_body,p_route);END IF;
END $$;
CREATE FUNCTION core.consumer_command(p_actor jsonb,p_person uuid,p_key uuid,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$
DECLARE old core.consumer_commands;target uuid:=gen_random_uuid();resource uuid;account uuid;other uuid;amount bigint;batch uuid;v core.consumer_vaults;c core.consumer_cards;details jsonb;result jsonb;secret text;allowed text[];BEGIN
 PERFORM core.consumer_actor(p_actor,p_person);IF p_key IS NULL OR p_key='00000000-0000-0000-0000-000000000000'::uuid OR jsonb_typeof(p_data)<>'object' THEN RAISE EXCEPTION 'Valid command key and input required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_person::text,307));
 SELECT * INTO old FROM core.consumer_commands WHERE issuer=p_actor->>'issuer' AND subject=p_actor->>'subject' AND client_id=p_actor->>'clientId' AND request_key=p_key;
 IF FOUND THEN IF old.person_id IS DISTINCT FROM p_person OR old.action IS DISTINCT FROM p_action OR old.input IS DISTINCT FROM p_data THEN RAISE EXCEPTION 'Command key scope conflict';END IF;RETURN old.result;END IF;
 allowed:=CASE p_action WHEN 'PREFERENCES' THEN ARRAY['theme','hideBalance','goals','notifications','marketing','riskLevel','onboardingComplete'] WHEN 'VAULT_CREATE' THEN ARRAY['name','targetMinor','targetDate','icon','mutual'] WHEN 'VAULT_UPDATE' THEN ARRAY['id','name','targetMinor','targetDate','icon','locked','mutual'] WHEN 'VAULT_DEPOSIT' THEN ARRAY['id','accountId','amountMinor'] WHEN 'VAULT_WITHDRAW' THEN ARRAY['id','accountId','amountMinor'] WHEN 'VAULT_INVITE' THEN ARRAY['id','receivingReference'] WHEN 'VAULT_JOIN' THEN ARRAY['id'] WHEN 'BUDGET' THEN ARRAY['category','limitMinor','rollover','threshold'] WHEN 'CARD_CREATE' THEN ARRAY['accountId','label'] WHEN 'CARD_UPDATE' THEN ARRAY['id','frozen','onlineEnabled','atmEnabled'] WHEN 'CARD_REVEAL' THEN ARRAY['authorizationId'] WHEN 'LINK_BANK' THEN ARRAY['institution','label','lastFour'] WHEN 'UNLINK_BANK' THEN ARRAY['id'] WHEN 'BILL_CREATE' THEN ARRAY['merchant','amountMinor','nextDate'] WHEN 'BILL_CANCEL' THEN ARRAY['id'] WHEN 'CATEGORY' THEN ARRAY['accountId','batchId','category','note','receipt'] WHEN 'REQUEST_MONEY' THEN ARRAY['accountId','receivingReference','amountMinor','memo'] WHEN 'REQUEST_CANCEL' THEN ARRAY['id'] WHEN 'NOTIFICATIONS_READ' THEN ARRAY['id'] WHEN 'TOKEN_CREATE' THEN ARRAY['authorizationId'] WHEN 'TOKEN_REVOKE' THEN ARRAY['id'] ELSE NULL END;
 IF allowed IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k<>ALL(allowed)) THEN RAISE EXCEPTION 'Unsupported command or fields';END IF;
 IF p_action='PREFERENCES' THEN
  IF (p_data?'hideBalance' AND jsonb_typeof(p_data->'hideBalance')<>'boolean') OR (p_data?'notifications' AND jsonb_typeof(p_data->'notifications')<>'boolean') OR (p_data?'marketing' AND jsonb_typeof(p_data->'marketing')<>'boolean') OR (p_data?'goals' AND (jsonb_typeof(p_data->'goals')<>'array' OR jsonb_path_exists(p_data,'$.goals[*] ? (@.type() != "string")'))) OR (p_data?'riskLevel' AND (p_data->>'riskLevel')::integer NOT BETWEEN 1 AND 5) THEN RAISE EXCEPTION 'Typed preferences required';END IF;
  IF coalesce(p_data->>'theme','light') NOT IN('light','dark','system') OR length(coalesce(p_data->>'goals',''))>2000 OR octet_length(p_data::text)>4096 THEN RAISE EXCEPTION 'Bounded supported preferences required';END IF;
  INSERT INTO core.consumer_preferences VALUES(p_person,p_data,clock_timestamp()) ON CONFLICT(person_id) DO UPDATE SET document=core.consumer_preferences.document||EXCLUDED.document,updated_at=EXCLUDED.updated_at;result:=jsonb_build_object('saved',true);
 ELSIF p_action='VAULT_CREATE' THEN
  IF length(p_data->>'name') NOT BETWEEN 1 AND 64 OR length(coalesce(p_data->>'icon','✦'))>8 THEN RAISE EXCEPTION 'Vault name and icon required';END IF;amount:=core.consumer_minor(p_data->>'targetMinor');
  IF (SELECT count(*) FROM core.consumer_vaults WHERE person_id=p_person)>=50 THEN RAISE EXCEPTION 'Vault limit reached';END IF;
  INSERT INTO core.ledger_accounts(id,kind,state,debit_blocked) VALUES(target,'CUSTOMER','ACTIVE',false);INSERT INTO core.consumer_vaults VALUES(target,p_person,p_data->>'name',amount,(p_data->>'targetDate')::date,coalesce(p_data->>'icon','✦'),false,coalesce((p_data->>'mutual')::boolean,false),clock_timestamp());INSERT INTO core.consumer_members VALUES(target,p_person,'ACTIVE');result:=jsonb_build_object('id',target,'state','ACTIVE');
 ELSIF p_action IN('VAULT_UPDATE','VAULT_DEPOSIT','VAULT_WITHDRAW','VAULT_INVITE','VAULT_JOIN') THEN
  resource:=(p_data->>'id')::uuid;SELECT * INTO STRICT v FROM core.consumer_vaults WHERE id=resource FOR UPDATE;
  IF p_action='VAULT_JOIN' THEN UPDATE core.consumer_members SET state='ACTIVE' WHERE vault_id=v.id AND person_id=p_person AND state='INVITED';IF NOT FOUND THEN RAISE EXCEPTION 'Invitation unavailable';END IF;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM core.consumer_members WHERE vault_id=v.id AND person_id=p_person AND state='ACTIVE') THEN RAISE EXCEPTION 'Vault unavailable';END IF;
   IF p_action='VAULT_UPDATE' THEN
    IF v.person_id<>p_person THEN RAISE EXCEPTION 'Vault owner required';END IF;
    IF p_data?'name' AND length(p_data->>'name') NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'Bounded vault name required';END IF;
    UPDATE core.consumer_vaults SET name=coalesce(p_data->>'name',name),target_minor=CASE WHEN p_data?'targetMinor' THEN core.consumer_minor(p_data->>'targetMinor') ELSE target_minor END,target_date=CASE WHEN p_data?'targetDate' THEN (p_data->>'targetDate')::date ELSE target_date END,locked=coalesce((p_data->>'locked')::boolean,locked),mutual=coalesce((p_data->>'mutual')::boolean,mutual) WHERE id=v.id;
   ELSIF p_action='VAULT_INVITE' THEN
    IF v.person_id<>p_person THEN RAISE EXCEPTION 'Vault owner required';END IF;
    SELECT r.person_id INTO STRICT other FROM core.receiving_references x JOIN core.account_relationships r ON r.account_id=x.account_id AND r.kind='OWNER' AND r.revoked_at IS NULL WHERE x.reference=p_data->>'receivingReference' LIMIT 1;
    INSERT INTO core.consumer_members VALUES(v.id,other,'INVITED') ON CONFLICT DO NOTHING;PERFORM core.consumer_notify(other,'Savings','Savings invitation',v.name,'/save/'||v.id);
   ELSE
    account:=(p_data->>'accountId')::uuid;PERFORM core.consumer_account(account,p_person);amount:=core.consumer_minor(p_data->>'amountMinor');
    IF p_action='VAULT_WITHDRAW' THEN IF v.locked OR (v.mutual AND (SELECT count(*) FROM core.consumer_members WHERE vault_id=v.id AND state='ACTIVE')>1) THEN RAISE EXCEPTION 'Unlock vault and obtain group withdrawal approval';END IF;batch:=core.consumer_post(target,'VAULT_WITHDRAWAL',v.id,account,amount);
    ELSE batch:=core.consumer_post(target,'VAULT_DEPOSIT',account,v.id,amount);END IF;
   END IF;
  END IF;result:=jsonb_build_object('id',resource,'batchId',batch,'state','SAVED');
 ELSIF p_action='BUDGET' THEN
  IF p_data->>'category' NOT IN('Dining','Groceries','Transport','Shopping','Utilities','Health','Travel','Other') THEN RAISE EXCEPTION 'Supported category required';END IF;
  INSERT INTO core.consumer_budgets VALUES(p_person,p_data->>'category',core.consumer_minor(p_data->>'limitMinor'),coalesce((p_data->>'rollover')::boolean,false),coalesce((p_data->>'threshold')::integer,80)) ON CONFLICT(person_id,category) DO UPDATE SET limit_minor=EXCLUDED.limit_minor,rollover=EXCLUDED.rollover,threshold=EXCLUDED.threshold;result:=jsonb_build_object('saved',true);
 ELSIF p_action='CARD_CREATE' THEN
  account:=(p_data->>'accountId')::uuid;PERFORM core.consumer_account(account,p_person);IF length(p_data->>'label') NOT BETWEEN 1 AND 64 OR (SELECT count(*) FROM core.consumer_cards WHERE person_id=p_person)>=20 THEN RAISE EXCEPTION 'Bounded card label and count required';END IF;
  INSERT INTO core.consumer_cards(id,person_id,account_id,label,last_four) VALUES(target,p_person,account,p_data->>'label',lpad(((hashtextextended(target::text,0)&2147483647)%10000)::text,4,'0'));result:=jsonb_build_object('id',target,'state','ACTIVE_SYNTHETIC');
 ELSIF p_action='CARD_UPDATE' THEN
  SELECT * INTO STRICT c FROM core.consumer_cards WHERE id=(p_data->>'id')::uuid AND person_id=p_person FOR UPDATE;PERFORM core.consumer_account(c.account_id,p_person);UPDATE core.consumer_cards SET frozen=coalesce((p_data->>'frozen')::boolean,frozen),online_enabled=coalesce((p_data->>'onlineEnabled')::boolean,online_enabled),atm_enabled=coalesce((p_data->>'atmEnabled')::boolean,atm_enabled) WHERE id=c.id;result:=jsonb_build_object('id',c.id,'saved',true);
 ELSIF p_action='CARD_REVEAL' THEN
  details:=core.consumer_approval(p_actor,p_person,(p_data->>'authorizationId')::uuid,'CARD_REVEAL');SELECT * INTO STRICT c FROM core.consumer_cards WHERE id=(details->>'id')::uuid AND person_id=p_person;PERFORM core.consumer_account(c.account_id,p_person);PERFORM core.consumer_approval(p_actor,p_person,(p_data->>'authorizationId')::uuid,'CARD_REVEAL');result:=jsonb_build_object('id',c.id,'cardToken','TST-'||upper(replace(c.id::text,'-','')),'lastFour',c.last_four,'network','SYNTHETIC_ONLY','expires',to_char(clock_timestamp()+interval '2 years','MM/YY'));
 ELSIF p_action='LINK_BANK' THEN
  IF length(p_data->>'institution') NOT BETWEEN 2 AND 64 OR length(p_data->>'label') NOT BETWEEN 1 AND 64 OR p_data->>'lastFour'!~'^[0-9]{4}$' THEN RAISE EXCEPTION 'Synthetic institution and masked account required';END IF;
  INSERT INTO core.consumer_links(id,person_id,institution,label,last_four) VALUES(target,p_person,p_data->>'institution',p_data->>'label',p_data->>'lastFour');result:=jsonb_build_object('id',target,'state','VERIFIED_SYNTHETIC','provider','LOCAL_SIMULATOR');
 ELSIF p_action='UNLINK_BANK' THEN
  UPDATE core.consumer_links SET state='REVOKED' WHERE id=(p_data->>'id')::uuid AND person_id=p_person;IF NOT FOUND THEN RAISE EXCEPTION 'Link unavailable';END IF;result:=jsonb_build_object('saved',true);
 ELSIF p_action='BILL_CREATE' THEN
  IF length(p_data->>'merchant') NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'Merchant required';END IF;
  INSERT INTO core.consumer_bills VALUES(target,p_person,p_data->>'merchant',core.consumer_minor(p_data->>'amountMinor'),(p_data->>'nextDate')::date,'ACTIVE',clock_timestamp());result:=jsonb_build_object('id',target,'state','ACTIVE');
 ELSIF p_action='BILL_CANCEL' THEN
  UPDATE core.consumer_bills SET state='CANCELLATION_REQUESTED' WHERE id=(p_data->>'id')::uuid AND person_id=p_person;IF NOT FOUND THEN RAISE EXCEPTION 'Bill unavailable';END IF;result:=jsonb_build_object('state','CANCELLATION_REQUESTED','notice','Request recorded; merchant cancellation is not confirmed.');
 ELSIF p_action='CATEGORY' THEN
  account:=(p_data->>'accountId')::uuid;PERFORM core.consumer_account(account,p_person);resource:=(p_data->>'batchId')::uuid;IF NOT EXISTS(SELECT 1 FROM core.journal_entries WHERE batch_id=resource AND account_id=account) OR length(coalesce(p_data->>'category','Other')) NOT BETWEEN 1 AND 32 OR length(coalesce(p_data->>'note',''))>240 OR octet_length(coalesce(p_data->'receipt','{}')::text)>48000 THEN RAISE EXCEPTION 'Owned bounded movement metadata required';END IF;
  IF p_data?'receipt' AND p_data->'receipt'<>'null'::jsonb AND (jsonb_typeof(p_data->'receipt')<>'object' OR p_data->'receipt'->>'mime' NOT IN('image/png','image/jpeg','application/pdf') OR coalesce(p_data->'receipt'->>'content','')!~'^[A-Za-z0-9+/]+={0,2}$' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data->'receipt') k WHERE k NOT IN('mime','content'))) THEN RAISE EXCEPTION 'Bounded supported receipt required';END IF;
  IF p_data?'receipt' AND p_data->'receipt'<>'null'::jsonb THEN PERFORM decode(p_data->'receipt'->>'content','base64');END IF;
  INSERT INTO core.consumer_metadata VALUES(account,resource,p_person,coalesce(p_data->>'category','Other'),coalesce(p_data->>'note',''),p_data->'receipt') ON CONFLICT(account_id,batch_id) DO UPDATE SET category=EXCLUDED.category,note=EXCLUDED.note,receipt=coalesce(EXCLUDED.receipt,core.consumer_metadata.receipt);result:=jsonb_build_object('saved',true);
 ELSIF p_action='REQUEST_MONEY' THEN
  account:=(p_data->>'accountId')::uuid;PERFORM core.consumer_account(account,p_person);IF length(coalesce(p_data->>'memo',''))>120 THEN RAISE EXCEPTION 'Bounded memo required';END IF;
  SELECT r.person_id INTO STRICT other FROM core.receiving_references x JOIN core.account_relationships r ON r.account_id=x.account_id AND r.kind='OWNER' AND r.revoked_at IS NULL WHERE x.reference=p_data->>'receivingReference' LIMIT 1;
  INSERT INTO core.consumer_requests VALUES(target,p_person,other,account,core.consumer_minor(p_data->>'amountMinor'),coalesce(p_data->>'memo',''),'REQUESTED',NULL,clock_timestamp());PERFORM core.consumer_notify(other,'Transactions','Payment request received',coalesce(p_data->>'memo',''),'/payments');result:=jsonb_build_object('id',target,'state','REQUESTED');
 ELSIF p_action='REQUEST_CANCEL' THEN
  UPDATE core.consumer_requests SET state='CANCELLED' WHERE id=(p_data->>'id')::uuid AND person_id=p_person AND state='REQUESTED';IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable';END IF;result:=jsonb_build_object('state','CANCELLED');
 ELSIF p_action='NOTIFICATIONS_READ' THEN
  UPDATE core.consumer_notifications SET read_at=clock_timestamp() WHERE person_id=p_person AND read_at IS NULL AND (p_data->>'id' IS NULL OR id=(p_data->>'id')::uuid);result:=jsonb_build_object('saved',true);
 ELSIF p_action='TOKEN_CREATE' THEN
  details:=core.consumer_approval(p_actor,p_person,(p_data->>'authorizationId')::uuid,'TOKEN_CREATE');IF length(details->>'label') NOT BETWEEN 1 AND 64 OR details->>'scope' NOT IN('accounts:read','transactions:read','portfolio:read') THEN RAISE EXCEPTION 'Supported token scope required';END IF;
  secret:='pb_test_'||replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');INSERT INTO core.consumer_tokens(id,person_id,actor_context,label,scope,secret_hash) VALUES(target,p_person,p_actor,details->>'label',details->>'scope',encode(sha256(convert_to(secret,'UTF8')),'hex'));result:=jsonb_build_object('id',target,'token',secret,'scope',details->>'scope','expiresAt',clock_timestamp()+interval '30 days');
 ELSIF p_action='TOKEN_REVOKE' THEN
  UPDATE core.consumer_tokens SET revoked_at=clock_timestamp() WHERE id=(p_data->>'id')::uuid AND person_id=p_person;IF NOT FOUND THEN RAISE EXCEPTION 'Token unavailable';END IF;result:=jsonb_build_object('saved',true);
 END IF;
 -- Tokens are only returned on the first successful response, never retained in receipts.
 INSERT INTO core.consumer_commands VALUES(target,p_actor->>'issuer',p_actor->>'subject',p_actor->>'clientId',p_key,p_person,p_action,p_data,result-'token',clock_timestamp());
 IF p_action NOT IN('NOTIFICATIONS_READ','PREFERENCES') THEN PERFORM core.consumer_notify(p_person,CASE WHEN p_action LIKE 'VAULT%' THEN 'Savings' ELSE 'Transactions' END,replace(initcap(lower(p_action)),'_',' '),'Your request was saved.','/home');END IF;RETURN result;
END $$;
CREATE FUNCTION core.consumer_snapshot(p_actor jsonb,p_person uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,core AS $$
DECLARE result jsonb;BEGIN PERFORM core.consumer_actor(p_actor,p_person);
 SELECT jsonb_build_object('source','CORE_AUTHORITATIVE','profile','SYNTHETIC_TST','observedAt',clock_timestamp(),'preferences',coalesce((SELECT document FROM core.consumer_preferences WHERE person_id=p_person),'{}'::jsonb),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'state',l.state,'bookedMinor',l.booked::text,'heldMinor',l.held::text,'availableMinor',(l.booked-l.held)::text)) FROM core.account_registry r JOIN core.ledger_accounts l ON l.id=r.id JOIN core.account_relationships x ON x.account_id=r.id AND x.person_id=p_person AND x.kind='OWNER' AND x.revoked_at IS NULL),'[]'::jsonb),
 'activity',coalesce((SELECT jsonb_agg(q ORDER BY q->>'at' DESC) FROM(SELECT jsonb_build_object('batchId',j.id,'accountId',e.account_id,'kind',j.posting_kind,'at',j.created_at,'date',j.business_date,'deltaMinor',e.delta::text,'category',coalesce(m.category,'Other'),'note',coalesce(m.note,''),'receipt',m.receipt,'originalBatchId',j.original_batch) q FROM core.journal_entries e JOIN core.journal_batches j ON j.id=e.batch_id JOIN core.account_relationships x ON x.account_id=e.account_id AND x.person_id=p_person AND x.kind='OWNER' AND x.revoked_at IS NULL LEFT JOIN core.consumer_metadata m ON m.batch_id=j.id AND m.account_id=e.account_id ORDER BY j.created_at DESC,j.id LIMIT 100) a),'[]'::jsonb),

 'vaults',coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'targetMinor',v.target_minor::text,'targetDate',v.target_date,'icon',v.icon,'locked',v.locked,'mutual',v.mutual,'bookedMinor',a.booked::text,'heldMinor',a.held::text,'membership',m.state,'isOwner',v.person_id=p_person,'members',(SELECT count(*) FROM core.consumer_members WHERE vault_id=v.id AND state='ACTIVE'))) FROM core.consumer_vaults v JOIN core.consumer_members m ON m.vault_id=v.id AND m.person_id=p_person JOIN core.ledger_accounts a ON a.id=v.id),'[]'::jsonb),
 'budgets',coalesce((SELECT jsonb_agg(jsonb_build_object('category',category,'limitMinor',limit_minor::text,'rollover',rollover,'threshold',threshold)) FROM core.consumer_budgets WHERE person_id=p_person),'[]'::jsonb),
 'cards',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'accountId',account_id,'label',label,'lastFour',last_four,'frozen',frozen,'onlineEnabled',online_enabled,'atmEnabled',atm_enabled,'network','SYNTHETIC_ONLY')) FROM core.consumer_cards WHERE person_id=p_person),'[]'::jsonb),
 'links',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'institution',institution,'label',label,'lastFour',last_four,'state',state)) FROM core.consumer_links WHERE person_id=p_person),'[]'::jsonb),
 'bills',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'merchant',merchant,'amountMinor',amount_minor::text,'nextDate',next_date,'state',state)) FROM core.consumer_bills WHERE person_id=p_person),'[]'::jsonb),
 'notifications',coalesce((SELECT jsonb_agg(q ORDER BY q->>'createdAt' DESC) FROM(SELECT jsonb_build_object('id',id,'category',category,'title',title,'body',body,'route',route,'readAt',read_at,'createdAt',created_at) q FROM core.consumer_notifications WHERE person_id=p_person ORDER BY created_at DESC LIMIT 100) n),'[]'::jsonb),
 'tokens',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'label',label,'scope',scope,'expiresAt',expires_at,'revokedAt',revoked_at)) FROM core.consumer_tokens WHERE person_id=p_person),'[]'::jsonb),
 'requests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'accountId',r.account_id,'reference',x.reference,'amountMinor',r.amount_minor::text,'memo',r.memo,'state',r.state,'incoming',r.recipient_person=p_person,'createdAt',r.created_at)) FROM core.consumer_requests r LEFT JOIN core.receiving_references x ON x.account_id=r.account_id WHERE r.person_id=p_person OR r.recipient_person=p_person),'[]'::jsonb)) INTO result;RETURN result;
END $$;
GRANT EXECUTE ON FUNCTION core.consumer_command(jsonb,uuid,uuid,text,jsonb),core.consumer_snapshot(jsonb,uuid),core.consumer_authorization(jsonb,uuid,uuid) TO bank_core;
